import {deflateSync} from 'node:zlib';
const crc=bytes=>{let n=0xffffffff;for(const byte of bytes){n^=byte;for(let i=0;i<8;i++)n=(n>>>1)^(n&1?0xedb88320:0);}return (n^0xffffffff)>>>0;};
const chunk=(type,data)=>{const name=Buffer.from(type),out=Buffer.alloc(data.length+12);out.writeUInt32BE(data.length);name.copy(out,4);data.copy(out,8);out.writeUInt32BE(crc(Buffer.concat([name,data])),out.length-4);return out;};
export function pictureBytes(seed=1,{width=96,height=64,noise=false}={}){
  const header=Buffer.alloc(13),raw=Buffer.alloc(height*(width*3+1));header.writeUInt32BE(width);header.writeUInt32BE(height,4);header[8]=8;header[9]=2;let random=seed;
  for(let y=0;y<height;y++)for(let x=0;x<width;x++){const at=y*(width*3+1)+1+x*3;if(noise){random^=random<<13;random^=random>>>17;random^=random<<5;raw[at]=random&255;raw[at+1]=random>>>8&255;raw[at+2]=random>>>16&255;}else{raw[at]=(x*3+seed*43)%256;raw[at+1]=(y*3+seed*19)%256;raw[at+2]=(x+y+seed*79)%256;}}
  return Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk('IHDR',header),chunk('IDAT',deflateSync(raw)),chunk('IEND',Buffer.alloc(0))]);
}
export const pictureSources=[1,2,3].map(seed=>'data:image/png;base64,'+pictureBytes(seed).toString('base64'));
export const pictureLabels=['A.','B.','Title:'];
export const pictureQuestions=['Descriptions of the photos A and B:','What do you think this text is mainly about?','What do you often do in your spare time? Do you spend your leisure time in an active or inactive way?'];
export const pictureAnswers=['Photo A shows a person relaxing on a sofa. Photo B shows a person using a tablet at home.','The text is mainly about quiet ways of relaxing during leisure time.','In my spare time, I often read books or listen to music. These are mostly inactive leisure activities.'];
export function pictureExerciseHTML({sources=pictureSources,grade=false}={}){
  return `<!doctype html><html><body><style>body{font:15px Arial}.layoutBody-container{display:grid;grid-template-columns:42% 58%}.layout-material-container figure{margin:12px;display:flex;align-items:center;gap:12px}.layout-material-container img{width:180px;height:100px}.question-inputbox{margin:20px 0}textarea{display:block;width:85%;height:80px}</style>
  <header><nav class="pc-break-crumb"><span class="pc-break-crumb-text">Complete English Book</span><span class="pc-break-crumb-text">Unit 1</span><span class="pc-break-crumb-text">Active reading</span></nav><div class="pc-header-tab-activity">Active reading</div><div class="pc-task pc-header-task-activity">Before you read</div></header>
  <main class="layout-container"><div class="abs-direction">Look at the photos A and B, and the title of the text. Describe the pictures and then answer the following questions.</div><div class="layoutBody-container"><div class="layout-material-container">${sources.map((src,index)=>`<figure><figcaption>${pictureLabels[index]}</figcaption><img src="${src}" alt="Material ${index+1}"></figure>`).join('')}</div><div class="question-common-abs-reply">${pictureQuestions.map((question,index)=>`<div class="question-inputbox"><div class="question-inputbox-header">${index+1}. ${question}</div><textarea id="picture-answer-${index}"></textarea></div>`).join('')}</div></div></main><button id="submit">提交</button><script>window.submitted=false;document.getElementById('submit').onclick=()=>{window.submitted=true;${grade?"document.querySelector('main').innerHTML='<h2>答题小结</h2><p>共 3 道题，客观题 0 道，主观题 3 道</p><p>正确 (3/3)</p><p>错误 (0/3)</p><p>未作答 0</p>';document.getElementById('submit').remove();":''}};</script></body></html>`;
}
